import {loadCardLogo,drawLearningCard} from './learning-card.js';
import {config as c} from './config.js';
import {storage} from './storage.js';
import {getAIResponse,validMessage} from './ai.js';
const u=c.ui,$=s=>document.querySelector(s),app=$('#app');
const base=new URL('../',import.meta.url),asset=p=>new URL(p,base).href;
const esc=s=>String(s).replace(/[&<>"']/g,x=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[x]));
const logo=(cls='logo')=>`<img class="${cls}" src="${asset('assets/logo.png')}" alt="نادي قوقل للمطورين، جامعة الطائف" width="245">`;
let toastTimer,kiosk=false,lastActivity=Date.now(),session=0,turn=0,scores=[65,65,65,65],answers=[],chosen=null,unlocked=false;
function toast(s){$('#toast').textContent=s;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),5500)}
const art=`<div class="art" aria-hidden="true"><svg viewBox="0 0 500 460" fill="none"><circle cx="250" cy="232" r="181" stroke="#cbd7bf" stroke-dasharray="3 9"/><circle cx="250" cy="232" r="143" stroke="#dce4d3"/><ellipse cx="252" cy="391" rx="118" ry="15" fill="#dce5d1"/><path d="M248 350C245 302 263 240 252 170" stroke="#527b4e" stroke-width="9" stroke-linecap="round"/><path d="M250 279C181 290 141 255 151 201C206 193 247 226 250 279Z" fill="#91b482"/><path d="M255 235C315 248 354 209 348 157C294 153 257 189 255 235Z" fill="#5c8c60"/><path d="M251 186C207 171 192 132 213 92C255 104 275 140 251 186Z" fill="#b0ca8d"/><path d="M247 272L179 225M261 227L324 181" stroke="#e1ecd4" stroke-width="2" stroke-linecap="round"/><path d="M208 325Q178 290 159 312Q144 329 175 354L226 399Q250 417 275 394L335 343Q355 323 336 310Q320 300 303 321L267 345" fill="#e9d4b0" stroke="#bda77f" stroke-width="2"/><path d="M171 351Q201 361 218 376M303 321L276 350Q259 361 241 348L213 326" stroke="#bda77f" stroke-width="2" stroke-linecap="round"/><circle cx="116" cy="139" r="11" fill="#f4c455"/><circle cx="374" cy="289" r="8" fill="#ea9385"/><circle cx="326" cy="85" r="6" fill="#7aa4eb"/><path d="M107 302v18M98 311h18M369 109v14M362 116h14" stroke="#87a67a" stroke-width="2" stroke-linecap="round"/></svg><div class="art-label top"><b>✦</b> كل خطوة صغيرة… تصنع فرقًا</div><div class="art-label bottom"><b style="color:#5d8d63">♡</b> أنت لست وحدك</div><span class="art-caption">وعي ينمو. وأمل يستمر.</span></div>`;
const path=location.pathname.replace(/\/$/,'');
if(path.endsWith('/wall'))renderWallPage();else if(path.endsWith('/admin'))renderAdmin();else renderHome();
function renderHome(){
 app.innerHTML=`<a class="skip button" href="#main">تجاوز إلى المحتوى</a><header class="header"><div class="shell header-inner"><a href="#" aria-label="الرئيسية">${logo()}</a><nav aria-label="التنقل الرئيسي">${c.nav.map((x,i)=>`<a href="${['#','#simulation','#companion','#hope-wall'][i]}">${x}</a>`).join('')}</nav><div class="tools"><button id="theme" aria-label="تبديل الوضع الفاتح والداكن">◐</button><a class="button help-link" href="#support">${u.help} ↗</a></div></div></header>
 <main id="main"><section class="shell hero"><div class="hero-copy"><span class="pill"><i class="dot"></i>${c.hero.eyebrow}</span><h1>${c.hero.line1}<span>${c.hero.line2}</span></h1><p>${c.hero.description}</p><div class="hero-actions"><a class="button primary" href="#simulation">${u.start} <span>←</span></a><a class="button" href="#hope-wall">اترك رسالة أمل ♡</a></div><div class="hero-note"><span>◷ تجربة قصيرة، وأثر يبقى</span><span>◎ مساحة آمنة بلا أحكام</span></div></div>${art}</section>
 <div class="shell journey"><div class="small-title">ثلاث تجارب، وهدف واحد: أنت بخير</div><div class="cards">${c.cards.map(x=>`<a class="entry-card" href="${x.link}"><div class="card-top"><span class="icon ${x.color}">${x.icon}</span><span class="number">${x.n} /</span></div><h3>${x.title}</h3><p>${x.desc}</p><div class="card-link"><span>${x.cta}</span><span>↖</span></div></a>`).join('')}</div></div>
 <section id="simulation" class="section simulation"><div class="shell"><div class="section-heading"><div><span class="eyebrow">01 / المحاكاة الرقمية للقرار</span><h2>${u.simulationTitle}</h2><p>${u.simulationIntro}</p></div><span class="pill">5 مواقف من الحياة</span></div><div class="sim-layout"><aside class="panel metrics" id="metrics"></aside><div class="panel scenario" id="scenario" aria-live="polite"></div></div></div></section>
 <section id="companion" class="section"><div class="shell split"><div><span class="eyebrow">02 / رفيق الأمل</span><div class="section-heading"><div><h2>${u.chatTitle}</h2><p>${u.chatIntro}</p></div></div><div class="big-symbol" aria-hidden="true">✳</div><p class="fine">${u.chatNote}</p><a href="#support" class="card-link">${u.help} ←</a></div><div class="panel chat"><div class="chat-head"><span class="icon green">✳</span><div><b>رفيق الأمل</b><small><i class="dot"></i>رفيق توعوي · إجابات جاهزة</small></div></div><div id="chat-log" class="chat-log" role="log" aria-live="polite" aria-label="المحادثة"></div><div class="suggestions">${c.suggestions.map(x=>`<button type="button" data-question="${x}">${x}</button>`).join('')}</div><form class="chat-form" id="chat-form"><input id="chat-input" aria-label="سؤالك لرفيق الأمل" placeholder="${u.chatPlaceholder}" maxlength="500" required autocomplete="off"><button class="primary" aria-label="إرسال السؤال">←</button></form></div></div></section>
 <section id="hope-wall" class="section wall-section"><div class="shell"><div class="section-heading"><div><span class="eyebrow">03 / جدار الأمل الرقمي</span><h2>${u.wallTitle}</h2><p>${u.wallIntro}</p></div><a class="button" href="${asset('wall/')}" target="_blank" rel="noopener">عرض الجدار ↗</a></div><div class="wall-grid" id="wall-grid"></div><form id="wall-form" class="wall-form"><div><label class="fine" for="wall-text">رسالتك، دون اسم</label><textarea id="wall-text" maxlength="150" placeholder="${u.messagePlaceholder}" required></textarea><div class="form-meta"><span>${u.wallNote}</span><span id="counter">0 / 150</span></div></div><div class="wall-controls"><label for="color">اللون</label><select id="color"><option value="green">أخضر</option><option value="blue">أزرق</option><option value="yellow">أصفر</option><option value="pink">وردي</option></select><label for="icon">الرمز</label><select id="icon"><option>♡</option><option>✦</option><option>❋</option><option>✧</option></select><button class="primary">${u.wallSend} ←</button></div></form></div></section>
 <section id="support" class="section"><div class="shell support"><div><span class="eyebrow">نحن أقرب مما تظن</span><h2>${u.helpTitle}</h2><p>${u.helpIntro}</p><p class="fine">عند خطر مباشر، اطلب الطوارئ المحلية أو توجّه لأقرب قسم طوارئ. تحقّق من الأرقام ونطاق الخدمة قبل نشر الموقع. آخر مراجعة: 21 أكتوبر 2026.</p></div><div>${c.support.map(x=>`<div class="support-row"><div><h3>${x.title}</h3><p>${x.desc}</p><small><a href="${x.url}" target="_blank" rel="noopener">المصدر الرسمي ↗</a></small></div><a class="phone" href="tel:${x.number}" aria-label="اتصل ${x.title} ${x.number}">${x.number}</a></div>`).join('')}</div></div></section></main>
 <footer class="footer"><div class="shell"><div class="footer-main"><div>${logo()}<p>${c.club}<br>${c.team}</p>${c.social.map(x=>`<a href="${esc(x.url)}">${esc(x.title)}</a>`).join('')}</div><div class="qr-box" id="qr-box"><img src="${asset('assets/qr.svg')}" alt="رمز QR لرابط المعاينة الخاصة"><div>خذ الأمل معك<br><span class="fine">رمز المعاينة الخاصة<br>يُستبدل برابط النشر العام</span></div></div></div><p>${u.privacy}</p><div class="footer-bottom"><span>صُنع بوعي، ليصنع فرقًا. <span style="color:#4285f4">●</span> <span style="color:#ea4335">●</span> <span style="color:#fbbc04">●</span> <span style="color:#34a853">●</span></span><div><button id="kiosk">⛶ وضع الكشك</button> <a href="${asset('admin/')}">إشراف الجدار</a></div></div></div></footer>`;
 renderSimulation();resetChat();renderNotes();storage.subscribe(renderNotes);
 $('#theme').onclick=()=>{document.body.classList.toggle('dark');$('#theme').setAttribute('aria-pressed',document.body.classList.contains('dark'))};
 $('#kiosk').onclick=toggleKiosk;
 $('#chat-form').onsubmit=e=>{e.preventDefault();sendChat($('#chat-input').value)};
 document.querySelectorAll('[data-question]').forEach(b=>b.onclick=()=>sendChat(b.dataset.question));
 $('#wall-text').oninput=()=>$('#counter').textContent=`${[...$('#wall-text').value].length} / 150`;
 $('#wall-form').onsubmit=async e=>{e.preventDefault();const text=$('#wall-text').value.trim();if(!validMessage(text))return toast(u.filterError);try{await storage.submit({text,color:$('#color').value,icon:$('#icon').value});$('#wall-form').reset();$('#counter').textContent='0 / 150';toast(u.pending)}catch{toast(u.storageError)}};
}
function renderSimulation(){
 $('#metrics').innerHTML=`<h3>أثر اختياراتك</h3>${c.metrics.map((x,i)=>`<div class="metric"><div class="metric-label"><label for="metric${i}">${x}</label><span>${scores[i]} / 100</span></div><progress id="metric${i}" max="100" value="${scores[i]}"></progress></div>`).join('')}<p class="fine">${u.simulationNote}</p>`;
 if(turn>=c.scenarios.length){$('#scenario').innerHTML=`<span class="pill">اكتملت الرحلة ✦</span><h3>${u.endTitle}</h3><p>${u.summaryNote}</p><h4>${u.learned}</h4><ul class="summary">${c.scenarios.map(s=>`<li>${s.skill}</li>`).join('')}</ul><div class="summary-actions"><button class="primary" id="share">${u.share}</button><button id="restart">${u.restart}</button></div>`;$('#restart').onclick=()=>resetSimulation();$('#share').onclick=downloadCard;return}
 const s=c.scenarios[turn];
 $('#scenario').innerHTML=`<div class="scenario-head"><span>${s.tag} · ${turn+1} / ${c.scenarios.length}</span><div class="steps" aria-hidden="true">${c.scenarios.map((_,i)=>`<i class="${i<=turn?'active':''}"></i>`).join('')}</div></div><h3 tabindex="-1" id="scenario-title">${s.title}</h3><p>${s.story}</p><div class="choices">${s.choices.map((x,i)=>`<button class="choice ${chosen===i?'selected':''}" data-choice="${i}" ${chosen!==null?'disabled':''}><b>${i+1}</b>${x}</button>`).join('')}</div>${chosen===null?'':`<div class="result"><div class="timeline">${s.outcomes[chosen].map((x,i)=>`<div><strong>${[u.days,u.months,u.years][i]}</strong>${x}</div>`).join('')}</div><div class="skill"><b>${u.best}: ${s.choices[s.best]}</b><br>${s.skill}</div><button class="primary" id="next">${turn===c.scenarios.length-1?u.learned:u.next} ←</button></div>`}`;
 document.querySelectorAll('[data-choice]').forEach(b=>b.onclick=()=>{chosen=Number(b.dataset.choice);answers.push(chosen);const safe=chosen===s.best;const deltas=safe?[7,8,6,9]:[-4,-3,-4,-2];scores=scores.map((n,i)=>Math.min(100,Math.max(0,n+deltas[i])));renderSimulation();$('#next').focus({preventScroll:true})});
 if($('#next'))$('#next').onclick=()=>{turn++;chosen=null;renderSimulation();($('#scenario-title')||$('#share')).focus({preventScroll:true})};
}
function resetSimulation(){turn=0;scores=[65,65,65,65];answers=[];chosen=null;renderSimulation()}
function resetChat(){session++;$('#chat-log').replaceChildren();bubble(c.replies.hello);$('#chat-input').value=''}
function bubble(text,user=false){const d=document.createElement('div');d.className='bubble'+(user?' user':'');d.textContent=text;$('#chat-log').append(d);$('#chat-log').scrollTop=$('#chat-log').scrollHeight}
async function sendChat(value){const text=value.trim();if(!text)return;const token=session;bubble(text,true);$('#chat-input').value='';try{const response=await getAIResponse(text);if(token===session)bubble(response)}catch{if(token===session)bubble(c.replies.fallback)}}
function noteHTML(x,seed=false){const color=['green','blue','pink','yellow'].includes(x.color)?x.color:'green';const icon=['♡','✦','❋','✧'].includes(x.icon)?x.icon:'♡';return `<article class="note ${color}"><span class="note-icon" aria-hidden="true">${icon}</span><p>${esc(x.text)}</p><small>${seed?'رسالة تحريرية من فريق الأمل':'رسالة من زائر · دون اسم'}</small></article>`}
async function renderNotes(){const el=$('#wall-grid');if(!el)return;const list=(await storage.list()).filter(x=>x.status==='approved');el.innerHTML=c.seeds.map(x=>noteHTML(x,true)).join('')+list.slice(-40).map(x=>noteHTML(x)).join('')}
function renderWallPage(){app.innerHTML=`<main class="wall-display"><header><a href="${base}">${logo()}</a><button id="fullscreen">⛶ ملء الشاشة</button></header><h1>${u.wallTitle}</h1><p style="text-align:center">${u.wallIntro}</p><div class="wall-grid" id="wall-grid"></div><p class="fine" style="text-align:center">${u.wallNote} · يتزامن العرض بين تبويبات هذا المتصفح.</p></main>`;renderNotes();storage.subscribe(renderNotes);$('#fullscreen').onclick=async()=>{try{if(!document.fullscreenElement)await document.documentElement.requestFullscreen();else await document.exitFullscreen()}catch{toast('ملء الشاشة غير متاح في هذا المتصفح.')}}}
async function passwordHash(p,salt){const bytes=new TextEncoder().encode(p);const key=await crypto.subtle.importKey('raw',bytes,'PBKDF2',false,['deriveBits']);const hash=await crypto.subtle.deriveBits({name:'PBKDF2',salt:new TextEncoder().encode(salt),iterations:150000,hash:'SHA-256'},key,256);return Array.from(new Uint8Array(hash),b=>b.toString(16).padStart(2,'0')).join('')}
async function renderAdmin(){
 let auth;try{auth=JSON.parse(localStorage.getItem('hope-admin')||'null')}catch{auth=null}
 app.innerHTML=`<main class="admin"><a href="${base}">${logo()}</a><h1>${u.adminTitle}</h1><p class="fine">${u.adminNote}</p>${unlocked?`<button id="logout">${u.logout}</button><div id="queue"></div>`:`<form id="admin-login"><label for="password">${auth?u.adminPassword:u.passwordSet}</label><input id="password" type="password" autocomplete="${auth?'current-password':'new-password'}" minlength="10" required><button class="primary">${auth?u.login:u.savePassword}</button></form>`}</main>`;
 if(!unlocked){$('#admin-login').onsubmit=async e=>{e.preventDefault();try{const p=$('#password').value;if(!auth){const salt=crypto.randomUUID();auth={salt,hash:await passwordHash(p,salt)};localStorage.setItem('hope-admin',JSON.stringify(auth));unlocked=true}else unlocked=await passwordHash(p,auth.salt)===auth.hash;if(unlocked)renderAdmin();else toast(u.passwordWrong)}catch{toast(u.storageError)}};return}
 $('#logout').onclick=()=>{unlocked=false;renderAdmin()};
 const list=await storage.list();$('#queue').innerHTML=list.length?list.map(x=>`<article class="panel"><span class="fine">${x.status==='pending'?'بانتظار المراجعة':'معتمدة'}</span><p>${esc(x.text)}</p><div class="admin-actions">${x.status==='pending'?`<button data-id="${esc(x.id)}" data-action="approved">${u.approve}</button>`:''}<button data-id="${esc(x.id)}" data-action="delete">${u.remove}</button></div></article>`).join(''):`<p>${u.noPending}</p>`;
 document.querySelectorAll('[data-action]').forEach(b=>b.onclick=async()=>{if(!unlocked)return;try{await storage.moderate(b.dataset.id,b.dataset.action);renderAdmin()}catch{toast(u.storageError)}});
}
async function toggleKiosk(){kiosk=!kiosk;document.body.classList.toggle('kiosk',kiosk);lastActivity=Date.now();$('#kiosk').textContent=kiosk?'إنهاء وضع الكشك · 60 ثانية':'⛶ وضع الكشك';try{if(kiosk&&!document.fullscreenElement)await document.documentElement.requestFullscreen();else if(!kiosk&&document.fullscreenElement)await document.exitFullscreen()}catch{toast('وضع الكشك يعمل؛ ملء الشاشة غير متاح هنا.')}}
['pointerdown','pointermove','keydown','input','touchstart','scroll'].forEach(event=>window.addEventListener(event,()=>lastActivity=Date.now(),{passive:true}));
setInterval(()=>{if(Date.now()-lastActivity<c.kioskSeconds*1000)return;if(unlocked){unlocked=false;renderAdmin()}if(!kiosk)return;lastActivity=Date.now();resetSimulation();resetChat();$('#wall-form').reset();$('#counter').textContent='0 / 150';window.scrollTo({top:0,behavior:'instant'});toast(u.reset)},1000);
async function downloadCard(){
 const button=$('#share');if(button)button.disabled=true;
 try{
  const [,logo]=await Promise.all([document.fonts.ready,loadCardLogo(asset('assets/logo.png'))]);
  const canvas=document.createElement('canvas');canvas.width=1080;canvas.height=1260;
  drawLearningCard(canvas.getContext('2d'),logo,c);
  const blob=await new Promise((resolve,reject)=>canvas.toBlob(b=>b?resolve(b):reject(new Error('PNG export failed')),'image/png'));
  const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='hope-learning.png';a.click();setTimeout(()=>URL.revokeObjectURL(url),5000);
 }catch{toast('تعذّر تحميل الشعار أو تصدير البطاقة. تحقق من الاتصال وحاول مجددًا.')}finally{if(button)button.disabled=false}
}
